//! Actual productive source demand, not incidental old facade cache reads.
use super::*;use std::{collections::BTreeSet,sync::Mutex};
struct Demand{denied_reads:BTreeSet<PathBuf>,denied_directories:BTreeSet<PathBuf>,calls:Mutex<Vec<(&'static str,PathBuf)>>}
impl Demand{fn call(&self,role:&'static str,path:&Path)->io::Result<()>{self.calls.lock().unwrap().push((role,path.to_path_buf()));if (role=="directory"&&self.denied_directories.contains(path))||(role!="directory"&&self.denied_reads.contains(path)){Err(io::Error::from_raw_os_error(1450))}else{Ok(())}}fn touched(&self,path:&Path)->bool{self.calls.lock().unwrap().iter().any(|(_,p)|p==path)}}
impl SnapshotProvider for Demand{
 fn stamp(&self,p:&Path)->io::Result<Stamp>{self.call("stamp",p)?;FileSystemInputs.stamp(p)}
 fn read(&self,p:&Path)->io::Result<(Stamp,Vec<u8>)>{self.call("read",p)?;FileSystemInputs.read(p)}
 fn list(&self,p:&Path)->io::Result<FolderListing>{self.call("list",p)?;FileSystemInputs.list(p)}
 fn read_policy_bounded(&self,p:&Path,n:usize)->io::Result<Option<CapturedInputRead>>{self.call("bounded",p)?;FileSystemInputs.read_policy_bounded(p,n)}
 fn policy_directory(&self,p:&Path,follow:bool,n:usize)->io::Result<Option<PolicyDirectoryListing>>{self.call("directory",p)?;FileSystemInputs.policy_directory(p,follow,n)}
}
fn create(root:&Path,path:&str,text:&str){let path=root.join(path);std::fs::create_dir_all(path.parent().unwrap()).unwrap();std::fs::write(path,text).unwrap();}
#[test]fn doc_productive_discovery_never_reads_archives_hidden_or_scope_exempt_sources_and_keeps_name_refusals(){
 let(_,request,root)=fixture("doc-productive-sources",0);
 for(path,text)in[("code/exempt/a.dm","/proc/exempt_only()\n    return\n"),("code/.private/a.dm","/proc/hidden_only()\n    return\n"),("code/single.dm","/proc/single_file_only()\n    return\n"),("doc/rewrite/archive/dead.md","```dm\narchive_missing()\n```\n"),("doc/rewrite/exempt.md","```dm\nexempt_missing()\n```\n"),("doc/rewrite/.hidden.md","```dm\nhidden_missing()\n```\n")]{create(&root,path,text)}
 create(&root,"doc/rewrite/a.md","```dm\nknown()\n    exempt_only()\n\u{2003}hidden_only()\nsingle_file_only()\n```\n");create(&root,"tools/ci/lint_scopes.toml","[lint.doc_snippets]\nexempt_prefixes=['code/exempt/']\nexempt_files=['code/single.dm','doc/rewrite/exempt.md']\n");
 let denied_reads=["code/exempt/a.dm","code/.private/a.dm","code/single.dm","doc/rewrite/archive/dead.md","doc/rewrite/exempt.md","doc/rewrite/.hidden.md","deepquarry.dme"].into_iter().map(|p|root.join(p)).collect();let denied_directories=["code/exempt","code/.private","doc/rewrite/archive"].into_iter().map(|p|root.join(p)).collect();let provider=Demand{denied_reads,denied_directories,calls:Mutex::new(Vec::new())};
 let inputs=RecordingInputs::new(&provider,0).with_initial_environment(dm_preprocess::InitialEnvironment::OriginalChecker0290);let db=Arc::new(crate::query_db::QueryDb::default());let intent=request.policy_inputs.unwrap().admit().unwrap();let(capture,owner)=crate::runner_host::workspace_capture::capture_raw_only(&inputs,&intent,&db).unwrap();assert_eq!(capture.raw_input_files().count(),2);assert!(!capture.covers_code_dm(&mut |_|Ok(())).unwrap());let scope=workspace_native_guard::NativeReadGuard::raw_owned(&capture,&owner,&db).unwrap();let before=provider.calls.lock().unwrap().len();let actual_config=capture.productive_doc_configuration().unwrap().unwrap();db.with_workspace_raw_tree(&capture,&scope,dq_analyze::captured_raw_tree_pages::Policy::DocSnippets,|data,config,_|{assert!(std::ptr::eq(actual_config,config),"reuse actual interpreted configuration owner, not a second parser");assert_eq!(data.sites().len(),3);assert_eq!(data.source_text(),["exempt_only()","hidden_only()","single_file_only()"]);assert!(data.sites().iter().all(|site|site.rel=="doc/rewrite/a.md"));assert_eq!(data.doc_blocks().unwrap().len(),1);Ok(())}).unwrap();assert_eq!(provider.calls.lock().unwrap().len(),before,"report consumes actual captured sources/config without fresh IO");for p in provider.denied_reads.iter().chain(&provider.denied_directories){assert!(!provider.touched(p),"irrelevant old facade work must not become required IO: {p:?}");}
 // Removing an exemption is a genuine newly required read, not empty text or an old scope grant.
 create(&root,"tools/ci/lint_scopes.toml","");let changed=RecordingInputs::new(&provider,0).with_initial_environment(dm_preprocess::InitialEnvironment::OriginalChecker0290);let failure=crate::runner_host::workspace_capture::capture_raw_only_with_prior(&changed,&intent,&db,Some(&capture)).err().unwrap();assert_eq!(failure.raw_os_error(),Some(1450));
}
#[test]fn doc_exact_file_exemptions_never_prune_a_directory_and_required_scope_io_stays_operational(){
 let(_,request,root)=fixture("doc-exact-file-not-subtree",0);create(&root,"code/nested/a.dm","/proc/needed()\n    return\n");create(&root,"tools/ci/lint_scopes.toml","[lint.doc_snippets]\nexempt_files=['code/nested/']\n");let provider=Demand{denied_reads:BTreeSet::from([root.join("code/nested/a.dm")]),denied_directories:Default::default(),calls:Mutex::new(Vec::new())};let inputs=RecordingInputs::new(&provider,0).with_initial_environment(dm_preprocess::InitialEnvironment::OriginalChecker0290);let db=Arc::new(crate::query_db::QueryDb::default());let intent=request.policy_inputs.unwrap().admit().unwrap();let error=crate::runner_host::workspace_capture::capture_raw_only(&inputs,&intent,&db).err().unwrap();assert_eq!(error.raw_os_error(),Some(1450));assert!(provider.touched(&root.join("code/nested/a.dm")));
}
#[test]fn doc_whole_subtree_exemption_is_authenticated_by_actual_config_and_code_cannot_be_inferred(){
 let(_,request,root)=fixture("doc-all-code-exempt",0);create(&root,"tools/ci/lint_scopes.toml","[lint.doc_snippets]\nexempt_prefixes=['code/']\n");let provider=Demand{denied_reads:Default::default(),denied_directories:BTreeSet::from([root.join("code")]),calls:Mutex::new(Vec::new())};let input=RecordingInputs::new(&provider,0).with_initial_environment(dm_preprocess::InitialEnvironment::OriginalChecker0290);let db=Arc::new(crate::query_db::QueryDb::default());let intent=request.policy_inputs.unwrap().admit().unwrap();let(capture,owner)=crate::runner_host::workspace_capture::capture_raw_only(&input,&intent,&db).unwrap();assert!(!provider.touched(&root.join("code")));assert_eq!(capture.raw_input_files().count(),1);assert!(!capture.covers_code_dm(&mut |_|Ok(())).unwrap());let guard=workspace_native_guard::NativeReadGuard::raw_owned(&capture,&owner,&db).unwrap();db.with_workspace_raw_tree(&capture,&guard,dq_analyze::captured_raw_tree_pages::Policy::DocSnippets,|data,_,_|{assert_eq!(data.sites().len(),2,"neither known nor missing exists in the actually excluded name index");Ok(())}).unwrap();
 create(&root,"tools/ci/lint_scopes.toml","");let input=RecordingInputs::new(&provider,0).with_initial_environment(dm_preprocess::InitialEnvironment::OriginalChecker0290);let error=crate::runner_host::workspace_capture::capture_raw_only_with_prior(&input,&intent,&db,Some(&capture)).err().unwrap();assert_eq!(error.raw_os_error(),Some(1450));
}
#[test]fn ownership_discovery_excludes_hidden_but_never_applies_lint_scopes_to_its_all_code_index(){
 let(_,mut request,root)=fixture("ownership-productive-code",0);create(&root,"code/.private/a.dm","/proc/hidden_not_owned()\n    return\n");create(&root,"code/visible.dm","/proc/visible_owned()\n    return\n");create(&root,"tools/ci/lint_scopes.toml","[lint.ownership]\nexempt_prefixes=['code/']\n");let policy=request.policy_inputs.as_mut().unwrap();policy.workspace_auxiliary=vec![Q::Ownership];policy.workspace.as_mut().unwrap().recursive_roots=vec![root.join("code")];let intent=request.policy_inputs.unwrap().admit().unwrap();let provider=Demand{denied_reads:BTreeSet::from([root.join("code/.private/a.dm")]),denied_directories:BTreeSet::from([root.join("code/.private"),root.join("doc/rewrite")]),calls:Mutex::new(Vec::new())};let inputs=RecordingInputs::new(&provider,0).with_initial_environment(dm_preprocess::InitialEnvironment::OriginalChecker0290);let db=Arc::new(crate::query_db::QueryDb::default());let(capture,_owner)=crate::runner_host::workspace_capture::capture_raw_only(&inputs,&intent,&db).unwrap();assert!(capture.covers_code_dm(&mut |_|Ok(())).unwrap());assert_eq!(capture.raw_input_files().count(),2,"both ordinary CODE files are indexed even under whole-code ownership exemption");assert!(provider.touched(&root.join("code/visible.dm")));for path in provider.denied_reads.iter().chain(&provider.denied_directories){assert!(!provider.touched(path));}
}
#[test]fn doc_real_missing_and_nondirectory_code_are_negative_source_facts_not_an_empty_semantic_model(){
 for file in [false,true]{let(_,request,root)=fixture("doc-negative-code",0);std::fs::remove_file(root.join("code/a.dm")).unwrap();std::fs::remove_dir(root.join("code")).unwrap();if file{std::fs::write(root.join("code"),"ordinary non-directory entry").unwrap();}let inputs=RecordingInputs::new(FileSystemInputs,0).with_initial_environment(dm_preprocess::InitialEnvironment::OriginalChecker0290);let intent=request.policy_inputs.unwrap().admit().unwrap();let db=Arc::new(crate::query_db::QueryDb::default());let(capture,owner)=crate::runner_host::workspace_capture::capture_raw_only(&inputs,&intent,&db).unwrap();assert_eq!(capture.raw_input_files().count(),1);let scope=workspace_native_guard::NativeReadGuard::raw_owned(&capture,&owner,&db).unwrap();db.with_workspace_raw_tree(&capture,&scope,dq_analyze::captured_raw_tree_pages::Policy::DocSnippets,|data,_,_|{assert_eq!(data.sites().len(),2);Ok(())}).unwrap();}
}

#[test]fn doc_nine_point_six_mb_code_and_large_prose_use_real_clean_demand_under_unchanged_family_limits(){
 let(_,request,root)=fixture("doc-actual-largest-clean-demand",0);let mut code=String::from("/proc/large_known(var/list/items = list(1, list(2, 3)))\n    return\n");let target=9_600_000usize;let line="// generated declarations representative text, no executable model needed\n";while code.len()+line.len()<=target{code.push_str(line)}code.extend(std::iter::repeat(' ').take(target-code.len()));assert_eq!(code.len(),target);create(&root,"code/large.dm",&code);
 let mut doc=String::new();let line="Ordinary documentation prose has no executable DM snippet or hidden input.\n";while doc.len()+line.len()<800_000{doc.push_str(line)}doc.push_str("```dm\nlarge_known()\n    missing_doc()\n```\n");create(&root,"doc/rewrite/a.md",&doc);
 let inputs=RecordingInputs::new(FileSystemInputs,0).with_initial_environment(dm_preprocess::InitialEnvironment::OriginalChecker0290);let db=Arc::new(crate::query_db::QueryDb::default());let before=db.db().stats(dm_query::Kind(4)).computed;let intent=request.policy_inputs.unwrap().admit().unwrap();let(capture,owner)=crate::runner_host::workspace_capture::capture_raw_only(&inputs,&intent,&db).unwrap();let scope=workspace_native_guard::NativeReadGuard::raw_owned(&capture,&owner,&db).unwrap();db.with_workspace_raw_tree_limit(&capture,&scope,dq_analyze::captured_raw_tree_pages::Policy::DocSnippets,64*1024*1024,|data,_,budget|{assert!(!budget.denied());assert!(budget.used()<=64*1024*1024);assert_eq!(data.sites().len(),1);assert_eq!(data.source_text(),["missing_doc()"]);assert_eq!(data.doc_blocks().unwrap().len(),1);Ok(())}).unwrap();assert_eq!(db.db().stats(dm_query::Kind(4)).computed,before,"a clean-only lexical report must never request a semantic body");
}
